// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1e18);

        // deposit via fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool dep, ) = address(c).call{value: amount}("");
        assertTrue(dep);

        // first withdraw should succeed
        vm.prank(actor);
        try c.withdraw() {
            // second withdraw must ALSO succeed: the mutex must be released after each call
            vm.prank(actor);
            bool ok;
            try c.withdraw() { ok = true; } catch { ok = false; }
            assertTrue(ok, "withdraw must be callable repeatedly");
        } catch {
            assertTrue(false, "first withdraw failed");
        }
    }
}
